mapper.select:
SELECT enter_time as field1, material_id field2, sum( quantity ) AS field3 FROM ( SELECT IF( HOUR ( enter_time ) >= 8, DATE_FORMAT( enter_time, '%Y-%m-%d' ), DATE_SUB( DATE_FORMAT( enter_time, '%Y-%m-%d' ), INTERVAL 1 DAY ) ) AS enter_time, ppo.material_id, pcsi.quantity FROM pms_complete_storage pcs JOIN pms_complete_storage_info pcsi ON pcsi.complete_storage_id = pcs.id JOIN pms_produce_order ppo ON pcsi.produce_order_id = ppo.id WHERE pcsi.del_flag = 0 AND ppo.del_flag = 0 AND pcs.state != 2 AND ppo.production_line_id in
#{productLineId}
AND pcs.enter_time >= #{start} AND pcs.enter_time < #{end} ) AS tt GROUP BY enter_time, material_id

SELECT DATE_FORMAT(enter_time,'%Y-%m') as field1, material_id field2, sum( quantity ) AS field3 FROM ( SELECT IF( HOUR ( enter_time ) >= 8, DATE_FORMAT( enter_time, '%Y-%m-%d' ), DATE_SUB( DATE_FORMAT( enter_time, '%Y-%m-%d' ), INTERVAL 1 DAY ) ) AS enter_time, ppo.material_id, pcsi.quantity FROM pms_complete_storage pcs JOIN pms_complete_storage_info pcsi ON pcsi.complete_storage_id = pcs.id JOIN pms_produce_order ppo ON pcsi.produce_order_id = ppo.id WHERE pcsi.del_flag = 0 AND ppo.del_flag = 0 AND pcs.state != 2 AND ppo.production_line_id in
#{productLineId}
AND pcs.enter_time >= #{start} AND pcs.enter_time < #{end} ) AS tt GROUP BY DATE_FORMAT(enter_time,'%Y-%m') , material_id

